function constrainedSubsetSum(nums, k) {
  // Try every non-empty set of positions and keep those whose gaps are all at most k.
  let best = -Infinity;
  for (let mask = 1; mask < (1 << nums.length); mask++) {
    let sum = 0, last = -1, ok = true;
    for (let i = 0; i < nums.length; i++) {
      if (!(mask & (1 << i))) continue;
      if (last !== -1 && i - last > k) { ok = false; break; }
      sum += nums[i];
      last = i;
    }
    if (ok && sum > best) best = sum;
  }
  return best;
}

