function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 12);
  const span = size === 'large' ? 10000 : [5, 20, 10000][Math.floor(rand() * 3)];
  const shift = rand() < 0.25 ? -span : 0;
  const nums = Array.from({ length: n }, () => {
    const value = Math.floor(rand() * (2 * span + 1)) - span + shift;
    return Math.max(-10000, Math.min(10000, value));
  });
  const k = rand() < 0.3 ? 1 + Math.floor(rand() * Math.min(n, 3)) : 1 + Math.floor(rand() * n);
  return [nums, k];
}
